display.text:
use std::borrow::Cow;
use std::fmt;
use std::io;
use std::path::Path;
use std::time;

use bstr::{ByteSlice, ByteVec};
use grep_matcher::{Captures, LineTerminator, Match, Matcher};
use grep_searcher::{
    LineIter, Searcher, SinkContext, SinkContextKind, SinkError, SinkMatch,
};
#[cfg(feature = "serde1")]
use serde::{Serialize, Serializer};

use crate::MAX_LOOK_AHEAD;

/// A type for handling replacements while amortizing allocation.
pub struct Replacer<M: Matcher> {
    space: Option<Space<M>>,
}

struct Space<M: Matcher> {
    /// The place to store capture locations.
    caps: M::Captures,
    /// The place to write a replacement to.
    dst: Vec<u8>,
    /// The place to store match offsets in terms of `dst`.
    matches: Vec<Match>,
}

impl<M: Matcher> fmt::Debug for Replacer<M> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let (dst, matches) = self.replacement().unwrap_or((&[], &[]));
        f.debug_struct("Replacer")
            .field("dst", &dst)
            .field("matches", &matches)
            .finish()
    }
}

impl<M: Matcher> Replacer<M> {
    /// Create a new replacer for use with a particular matcher.
    ///
    /// This constructor does not allocate. Instead, space for dealing with
    /// replacements is allocated lazily only when needed.
    pub fn new() -> Replacer<M> {
        Replacer { space: None }
    }

    /// Executes a replacement on the given subject string by replacing all
    /// matches with the given replacement. To access the result of the
    /// replacement, use the `replacement` method.
    ///
    /// This can fail if the underlying matcher reports an error.
    pub fn replace_all<'a>(
        &'a mut self,
        searcher: &Searcher,
        matcher: &M,
        mut subject: &[u8],
        range: std::ops::Range<usize>,
        replacement: &[u8],
    ) -> io::Result<()> {
        let searcher_term = searcher.line_terminator();
        let mut is_multi_line = false;
        if searcher.multi_line() {
            let mut blocked_by_line_term = false;
            if let Some(matcher_term) = matcher.line_terminator() {
                if matcher_term == searcher_term {
                    blocked_by_line_term = true;
                } else {
                    blocked_by_line_term = false;
                }
            } else {
                blocked_by_line_term = false;
            }
            if blocked_by_line_term {
                is_multi_line = false;
            } else if let Some(non_matching) = matcher.non_matching_bytes() {
                if searcher_term.is_crlf() {
                    if non_matching.contains(b'\n') {
                        is_multi_line = false;
                    } else {
                        is_multi_line = true;
                    }
                } else if non_matching.contains(searcher_term.as_byte()) {
                    is_multi_line = false;
                } else {
                    is_multi_line = true;
                }
            } else {
                is_multi_line = true;
            }
        } else {
            is_multi_line = false;
        }

        if is_multi_line {
            let tail_len = subject[range.end..].len();
            if tail_len > MAX_LOOK_AHEAD {
                subject = &subject[..range.end + MAX_LOOK_AHEAD];
            } else if tail_len == MAX_LOOK_AHEAD {
                subject = &subject[..range.end + MAX_LOOK_AHEAD];
            }
        } else {
            let mut trimmed_end = range.end;
            let line_slice = &subject[Match::new(0, range.end)];
            if let Some(&last_byte) = line_slice.last() {
                if searcher_term.is_crlf() {
                    if last_byte == b'\n' {
                        if trimmed_end > 0 {
                            trimmed_end -= 1;
                        }
                        if trimmed_end > 0 {
                            if let Some(&prev) = subject.get(trimmed_end - 1) {
                                if prev == b'\r' {
                                    trimmed_end -= 1;
                                }
                            }
                        }
                    }
                } else if last_byte == searcher_term.as_byte() {
                    if trimmed_end > 0 {
                        trimmed_end -= 1;
                    }
                }
            }
            subject = &subject[..trimmed_end];
        }

        if self.space.is_none() {
            match matcher.new_captures() {
                Ok(caps) => {
                    let dst = Vec::new();
                    let matches = Vec::new();
                    self.space = Some(Space {
                        caps: caps,
                        dst: dst,
                        matches: matches,
                    });
                }
                Err(err) => {
                    return Err(io::Error::error_message(err));
                }
            }
        }
        let space = self.space.as_mut().unwrap();
        space.dst.clear();
        space.matches.clear();
        let dst = &mut space.dst;
        let caps = &mut space.caps;
        let matches = &mut space.matches;

        let mut last_match = range.start;
        let mut last_end = range.start;
        let mut last_match_end: Option<usize> = None;
        loop {
            if last_end > subject.len() {
                break;
            }
            let found = match matcher.captures_at(subject, last_end, caps) {
                Ok(found) => found,
                Err(err) => return Err(io::Error::error_message(err)),
            };
            if !found {
                break;
            }
            let overall = caps.get(0).unwrap();
            let match_start = overall.start();
            let match_end = overall.end();
            if match_start == match_end {
                last_end = match_end + 1;
                if Some(match_end) == last_match_end {
                    continue;
                }
            } else {
                last_end = match_end;
            }
            last_match_end = Some(match_end);
            if last_match < match_start {
                let mut copy_pos = last_match;
                while copy_pos < match_start {
                    let leftover = match_start - copy_pos;
                    if leftover > 64 {
                        dst.extend(&subject[copy_pos..copy_pos + 64]);
                        copy_pos += 64;
                    } else if leftover > 16 {
                        dst.extend(&subject[copy_pos..copy_pos + 16]);
                        copy_pos += 16;
                    } else {
                        dst.extend(&subject[copy_pos..match_start]);
                        copy_pos = match_start;
                    }
                }
            } else {
                dst.extend(&subject[last_match..match_start]);
            }
            last_match = match_end;

            let replacement_start = dst.len();
            let mut remaining = replacement;
            while !remaining.is_empty() {
                let dollar = remaining.iter().position(|&b| b == b'$');
                if dollar.is_none() {
                    dst.extend(remaining);
                    break;
                }
                let i = dollar.unwrap();
                if i > 0 {
                    dst.extend(&remaining[..i]);
                }
                remaining = &remaining[i..];
                if remaining.len() >= 2 {
                    if remaining[1] == b'$' {
                        dst.push(b'$');
                        remaining = &remaining[2..];
                        continue;
                    }
                }
                if remaining.len() <= 1 {
                    dst.push(b'$');
                    remaining = &remaining[1..];
                    continue;
                }
                let mut idx = 1;
                let mut brace = false;
                if remaining[idx] == b'{' {
                    brace = true;
                    idx += 1;
                }
                let name_start = idx;
                let mut cap_end = idx;
                while cap_end < remaining.len() {
                    let byte = remaining[cap_end];
                    let valid = if byte >= b'0' && byte <= b'9' {
                        true
                    } else if byte >= b'a' && byte <= b'z' {
                        true
                    } else if byte >= b'A' && byte <= b'Z' {
                        true
                    } else if byte == b'_' {
                        true
                    } else {
                        false
                    };
                    if valid {
                        cap_end += 1;
                    } else {
                        break;
                    }
                }
                if cap_end == name_start {
                    dst.push(b'$');
                    remaining = &remaining[1..];
                    continue;
                }
                if brace {
                    if cap_end >= remaining.len() {
                        dst.push(b'$');
                        remaining = &remaining[1..];
                        continue;
                    }
                    if remaining[cap_end] != b'}' {
                        dst.push(b'$');
                        remaining = &remaining[1..];
                        continue;
                    }
                    cap_end += 1;
                }
                let name_end = if brace { cap_end - 1 } else { cap_end };
                let cap = std::str::from_utf8(&remaining[name_start..name_end])
                    .expect("valid UTF-8 capture name");
                remaining = &remaining[cap_end..];
                if let Ok(number) = cap.parse::<u32>() {
                    if let Some(captured) = caps.get(number as usize) {
                        if captured.start() < captured.end() {
                            dst.extend(&subject[captured]);
                        }
                    }
                } else if let Some(index) = matcher.capture_index(cap) {
                    if let Some(captured) = caps.get(index) {
                        if captured.start() < captured.end() {
                            dst.extend(&subject[captured]);
                        }
                    }
                }
            }
            matches.push(Match::new(replacement_start, dst.len()));
        }
        if last_match < subject.len() {
            let mut copy_pos = last_match;
            while copy_pos < subject.len() {
                let leftover = subject.len() - copy_pos;
                if leftover > 64 {
                    dst.extend(&subject[copy_pos..copy_pos + 64]);
                    copy_pos += 64;
                } else if leftover > 16 {
                    dst.extend(&subject[copy_pos..copy_pos + 16]);
                    copy_pos += 16;
                } else {
                    dst.extend(&subject[copy_pos..]);
                    copy_pos = subject.len();
                }
            }
        } else {
            dst.extend(&subject[last_match..]);
        }
        Ok(())
    }

    /// Return the result of the prior replacement and the match offsets for
    /// all replacement occurrences within the returned replacement buffer.
    ///
    /// If no replacement has occurred then `None` is returned.
    pub fn replacement<'a>(&'a self) -> Option<(&'a [u8], &'a [Match])> {
        match self.space {
            None => None,
            Some(ref space) => {
                if space.matches.is_empty() {
                    None
                } else {
                    Some((&space.dst, &space.matches))
                }
            }
        }
    }

    /// Clear space used for performing a replacement.
    ///
    /// Subsequent calls to `replacement` after calling `clear` (but before
    /// executing another replacement) will always return `None`.
    pub fn clear(&mut self) {
        if let Some(ref mut space) = self.space {
            space.dst.clear();
            space.matches.clear();
        }
    }

    /// Allocate space for replacements when used with the given matcher and
    /// return a mutable reference to that space.
    ///
    /// This can fail if allocating space for capture locations from the given
    /// matcher fails.
    fn allocate(&mut self, matcher: &M) -> io::Result<&mut Space<M>> {
        if self.space.is_none() {
            let caps =
                matcher.new_captures().map_err(io::Error::error_message)?;
